package vn.tuan.service;
import lombok.RequiredArgsConstructor;import org.springframework.stereotype.Service;import org.springframework.transaction.annotation.Transactional;import org.springframework.web.multipart.MultipartFile;import java.time.*;import java.util.*;import vn.tuan.entity.*;import vn.tuan.repository.*;
@Service @RequiredArgsConstructor public class CustomerService {
 private final ProductActivityRepository activity;private final ActorService actors;private final ProductRepository products;private final OrderRepository orders;private final ReviewRepository reviews;private final MediaService media;
 @Transactional public void activity(String email,Integer productId,boolean toggle){Account a=actors.account(email);Product p=products.findById(productId).orElseThrow();OrderRules.require("ACTIVE".equals(p.getStatus()) && "ACTIVE".equals(p.getShop().getStatus()),"Món đã ngừng bán");ProductActivity x=activity.findByAccountAndProduct(a,p).orElseGet(()->{var n=new ProductActivity();n.setAccount(a);n.setProduct(p);return n;});x.setViewedAt(LocalDateTime.now());if(toggle)x.setFavorite(!x.isFavorite());activity.save(x);}
 public List<ProductActivity> history(String email){return activity.findByAccountOrderByViewedAtDesc(actors.account(email));}
 @Transactional public void review(String email,Integer orderId,Integer productId,int rating,String comment,MultipartFile file){Account a=actors.account(email);Order o=orders.lockById(orderId).orElseThrow();OrderRules.require(o.getAccount()!=null && o.getAccount().getId().equals(a.getId()) && "COMPLETED".equals(o.getStatus()),"Chỉ đánh giá đơn của mình đã giao thành công");Product p=products.findById(productId).orElseThrow();OrderRules.require(o.getOrderDetails().stream().anyMatch(d->d.getProduct().getId().equals(productId)),"Sản phẩm không nằm trong đơn");OrderRules.require(rating>=1 && rating<=5 && comment!=null && comment.trim().length()>=50 && comment.length()<=4000,"Đánh giá từ 1–5 sao; nội dung từ 50–4000 ký tự");OrderRules.require(!reviews.existsByAccountAndProductAndOrder(a,p,o),"Sản phẩm trong đơn này đã được đánh giá");String url=media.upload(file,true);reviews.save(Review.builder().account(a).order(o).product(p).rating(rating).comment(comment.trim()).mediaUrl(url).build());}
}
